        edges.append((i+8, j+8))
# Between cliques
for i in range(4):
    edges.append((i, i+4))
    edges.append((i+4, i+8))

def solve_graceful():
    n_vertices = 12

    # adjacency list
    adj = [[] for _ in range(n_vertices)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Sort vertices by degree (higher degree first - fail faster)
    degrees = [len(adj[v]) for v in range(n_vertices)]
    vertex_order = sorted(range(n_vertices), key=lambda x: -degrees[x])

    print("Degrees:", degrees)
    print("Vertex order:", vertex_order)

    # Backtracking
    labels = [None] * n_vertices
    used_labels = set()
    used_edge_labels = set()

    def backtrack(pos):
        if pos == n_vertices:
            return True

        v = vertex_order[pos]

        # Try labels - maybe try extremes and middle
        candidates = []
        # Add 0, 26, 1, 25, 2, 24, ...
        for i in range(27):
            if i % 2 == 0:
                candidates.append(i // 2)
            else:
                candidates.append(26 - i // 2)

        for label in candidates:
            if label in used_labels:
                continue

            # Check edge labels with already labeled neighbors
            valid = True
            new_edge_labels = []
            for u in adj[v]:
                if labels[u] is not None:
                    edge_label = abs(label - labels[u])
                    if edge_label == 0 or edge_label in used_edge_labels or edge_label in new_edge_labels:
                        valid = False
                        break
                    new_edge_labels.append(edge_label)

            if not valid:
                continue

            # Place label
            labels[v] = label
            used_labels.add(label)
            for el in new_edge_labels:
                used_edge_labels.add(el)

            if backtrack(pos + 1):
                return True

            # Backtrack
            labels[v] = None
            used_labels.remove(label)
            for el in new_edge_labels:
                used_edge_labels.remove(el)

        return False

    if backtrack(0):
        # Return labels in original vertex order
        result = [0] * n_vertices
        for v in range(n_vertices):
            result[v] = labels[v]
        return result
    else:
        return None

print("Starting backtracking...")
result = solve_graceful()
